function initIntegrations(){if(localStorage.getItem("pw-consent")!=="granted")return;if(site.analyticsId&&!document.querySelector("script[data-palworld-ga]")){const script=document.createElement("script");script.async=true;script.src=`https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(site.analyticsId)}`;script.dataset.palworldGa="true";document.head.append(script);const win=window as Window&{dataLayer?:unknown[][];gtag?:(...args:unknown[])=>void};win.dataLayer=win.dataLayer||[];win.gtag=(...args)=>win.dataLayer!.push(args);win.gtag("js",new Date());win.gtag("config",site.analyticsId,{send_page_view:false});trackPageView()}if(import.meta.env.PROD&&site.adsenseClient&&!document.querySelector("script[data-palworld-ads]")){const script=document.createElement("script");script.async=true;script.crossOrigin="anonymous";script.src=`https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${encodeURIComponent(site.adsenseClient)}`;script.dataset.palworldAds="true";document.head.append(script)}}
function ensureItemData(){if(itemData||itemLoading)return;itemLoading=true;fetch("/data/items.json").then(r=>{if(!r.ok)throw new Error(`Item data load ${r.status}`);return r.json()}).then((loaded:ItemData)=>{if(loaded.meta.gameBuild!==site.gameBuild||loaded.meta.localeCount!==locales.length||loaded.meta.itemCount!==loaded.items.length||loaded.meta.recipeCount!==loaded.recipes.length)throw new Error("Item dataset verification mismatch");itemData=loaded;render()}).catch(error=>console.error(error)).finally(()=>{itemLoading=false})}
